// Deterministic SLA assertion — no LLM needed for happy path
const progress = $input.item.json;
const slas = $('Get Active Regions').item.json.slasSeconds;

const stages = ['CAPTURED', 'VALIDATED', 'ENRICHED', 'RISK_CALCULATED', 'BOOKED'];
const currentStage = progress.currentStage;
const stageTimestamps = progress.stageTimestamps || {};

let stuck = false;
let stuckStage = null;
let elapsedSeconds = 0;
let expectedSla = 0;

// Check if we've progressed past minimum expected stage for elapsed time
const totalElapsed = (Date.now() - new Date(progress.injectedAt).getTime()) / 1000;

if (currentStage === 'CAPTURED' && totalElapsed > slas.CAPTURED_TO_VALIDATED) {
  stuck = true;
  stuckStage = 'VALIDATED';
  elapsedSeconds = totalElapsed;
  expectedSla = slas.CAPTURED_TO_VALIDATED;
} else if (currentStage === 'VALIDATED' && totalElapsed > (slas.CAPTURED_TO_VALIDATED + slas.VALIDATED_TO_ENRICHED)) {
  stuck = true;
  stuckStage = 'ENRICHED';
  elapsedSeconds = totalElapsed - slas.CAPTURED_TO_VALIDATED;
  expectedSla = slas.VALIDATED_TO_ENRICHED;
} else if (currentStage === 'ENRICHED' && totalElapsed > (slas.CAPTURED_TO_VALIDATED + slas.VALIDATED_TO_ENRICHED + slas.ENRICHED_TO_RISK_CALCULATED)) {
  stuck = true;
  stuckStage = 'RISK_CALCULATED';
  elapsedSeconds = totalElapsed - slas.CAPTURED_TO_VALIDATED - slas.VALIDATED_TO_ENRICHED;
  expectedSla = slas.ENRICHED_TO_RISK_CALCULATED;
}

return [{
  json: {
    stuck,
    stuckStage,
    currentStage,
    elapsedSeconds: Math.round(elapsedSeconds),
    expectedSlaSecs: expectedSla,
    tradeId: $('Inject Synthetic Trade').item.json.tradeId,
    region: $('Loop Regions').item.json.name,
    probeTimestamp: $('Get Active Regions').item.json.probeTimestamp,
    stageTimestamps
  }
}];

